<div class="container-wide section"><div class="breadcrumb-line"><a href="<?= e(url('shop')) ?>">The pantry</a> / <?= e($product['name']) ?></div><div class="product-detail"><div><a class="detail-image" href="<?= e(asset($product['image'])) ?>" target="_blank" rel="noopener" aria-label="Open full-size product image"><img id="main-product-image" src="<?= e(asset($product['image'])) ?>" alt="<?= e($product['name']) ?>"></a><div class="gallery-thumbs"><?php foreach(array_merge([['path'=>$product['image']]],$images) as $im): ?><button class="gallery-thumb" data-src="<?= e(asset($im['path'])) ?>"><img src="<?= e(asset($im['path'])) ?>" alt="View product image"></button><?php endforeach ?></div><p class="small muted">Click the image to view full size.</p></div><div class="product-detail-copy"><span class="eyebrow"><?= e($product['category_name']) ?></span><h1><?= e($product['name']) ?></h1><p class="lead"><?= e($product['short_description']) ?></p><?php if($reviews): ?><p class="stars">★ <?= number_format(array_sum(array_column($reviews,'rating'))/count($reviews),1) ?> · <?= count($reviews) ?> reviews</p><?php endif ?><p><?= nl2br(e($product['description'])) ?></p><?php if($variants): $v=$variants[0]; ?><form class="add-cart-form" method="post" action="<?= e(url('cart/add')) ?>"><?= csrf() ?><div class="detail-price"><span class="price" data-price><?= money($v['price']) ?></span> <del data-compare><?= $v['compare_price']>$v['price']?money($v['compare_price']):'' ?></del></div><label class="form-label">Choose your jar<select class="form-select variant-select" name="variant_id"><?php foreach($variants as $v): ?><option value="<?= $v['id'] ?>" data-price="<?= $v['price'] ?>" data-compare="<?= $v['compare_price'] ?>" data-stock="<?= $v['stock'] ?>"><?= e($v['label']) ?> — <?= money($v['price']) ?></option><?php endforeach ?></select></label><div class="stock-message"><?= $variants[0]['stock']?'In stock · ready for your pantry':'Currently sold out' ?></div><div class="purchase-row"><label class="visually-hidden" for="quantity">Quantity</label><input id="quantity" class="form-control quantity" type="number" name="quantity" min="1" max="50" value="1"><button class="btn btn-primary add-button" <?= !$variants[0]['stock']?'disabled':'' ?>><?= $variants[0]['stock']?'Add to bag　+':'Sold out' ?></button></div></form><?php endif ?><div class="detail-assurances"><span>Carefully packed</span><span>Free delivery above <?= money(setting('free_shipping','79900')) ?></span></div><?php foreach(['ingredients'=>'Ingredients','allergens'=>'Allergen information','storage'=>'Storage instructions','shelf_life'=>'Shelf life'] as $key=>$label): ?><details><summary><?= e($label) ?></summary><p><?= nl2br(e($product[$key]?:'Information has not yet been supplied. Please contact the store before ordering if you have specific requirements.')) ?></p></details><?php endforeach ?></div></div><section class="section"><h2>From the people who tried it.</h2><div class="review-grid"><?php foreach($reviews as $review) require ROOT.'/app/Views/store/review.php'; ?></div><?php if(!$reviews): ?><p class="muted">No reviews yet. Purchased this jar? Share your thoughts after delivery.</p><?php endif ?><?php if(user()): ?><form action="<?= e(url('review')) ?>" method="post" enctype="multipart/form-data" class="panel review-form"><?= csrf() ?><input type="hidden" name="product_id" value="<?= $product['id'] ?>"><h3>Share your experience</h3><label>Rating<select class="form-select" name="rating"><?php for($n=5;$n>=1;$n--): ?><option value="<?= $n ?>"><?= $n ?> stars</option><?php endfor ?></select></label><label>Your review<textarea class="form-control" name="body" minlength="10" required></textarea></label><label>Photo (optional)<input class="form-control" type="file" name="review_image" accept="image/jpeg,image/png,image/webp"></label><button class="btn btn-primary">Submit for review</button></form><?php endif ?></section><div class="section-heading"><h2>More for your table.</h2></div><div class="product-grid"><?php foreach($related as $p) require ROOT.'/app/Views/store/card.php'; ?></div></div>
